      {
        "id": "d7a3a491-a636-3416-baf5-0bc6e1b2f342",
        "sourceId": "a8352f89-8db6-3b5c-9485-5e7145938166",
        "form": "A",
        "expectedMeta": {
          "key": "b09-a-expanded-listening-7",
          "objective": "goal1",
          "itemType": "verbal_expression",
          "distractorReasons": [
            "Ini menyatakan kembali dari sekolah, bukan datang ke sekolah.",
            "Ini menyatakan kembali ke rumah, bertentangan dengan tujuan sekolah.",
            "きます menyatakan datang menuju sekolah tempat A berada; dua pilihan lain mengubah arah gerak."
          ],
          "spokenChoices": [
            "Bさんは あした この がっこうから かえります。",
            "Bさんは あした うちへ かえります。",
            "Bさんは あした この がっこうへ きます。"
          ]
        },
        "revision": {
          "fields": {
            "audio_script": "N: A berada di sekolah ini dan besok tetap berada di sini untuk menunggu kedatangan B. B sekarang di rumahnya. Besok adalah kunjungan pertama B ke sekolah ini. Dari sudut pandang A, pilih ucapan yang menyatakan gerak B menuju tempat A berada.\nN: いちばん。\nA: Bさんは あした この がっこうへ きます。\nN: にばん。\nA: Bさんは あした この がっこうへ いきます。\nN: さんばん。\nA: Bさんは あした この がっこうへ かえります。",
            "image_url": "/assets/assessments/speakers-ab.svg",
            "explanation": "A berada di sekolah tujuan dan akan menunggu B di sana. Gerak B menuju tempat A dinyatakan きます. Semua pilihan mempertahankan pelaku, waktu, dan tujuan yang sama; yang dibedakan adalah verba arah.",
            "section_label": "ばめんに あう ことば",
            "section_instruction": "えは Aさんと Bさんを あらわします。ばめんと こたえは こえで ききます。Aさんの ことばを えらんで ください。\nGambar menunjukkan tokoh A dan B. Dengarkan situasi dan tiga ucapan; pilih ucapan A."
          },
          "meta": {
            "version": "n5-assessment-v6",
            "key": "b09-a-expanded-listening-7-reviewed",
            "objectiveEvidence": true,
            "distractorReasons": [
              "きます menyatakan gerak mendekati tempat A berada, sesuai sudut pandang yang diberikan.",
              "いきます tidak menyatakan gerak mendekati tempat A yang menunggu di sekolah tujuan pada situasi ini.",
              "かえります menyatakan kembali; ini kunjungan pertama B ke sekolah tersebut, sehingga bukan kembali ke tempat asalnya."
            ],
            "spokenChoices": [
              "Bさんは あした この がっこうへ きます。",
              "Bさんは あした この がっこうへ いきます。",
              "Bさんは あした この がっこうへ かえります。"
            ]
          },
          "expected": {
            "audio_script": "N: A sedang berada di sekolah. B berada di rumahnya dan besok akan menuju sekolah tempat A berada. Pilih ucapan A yang menjelaskan gerak B menuju tempat A.\nN: いちばん。\nA: Bさんは あした この がっこうから かえります。\nN: にばん。\nA: Bさんは あした うちへ かえります。\nN: さんばん。\nA: Bさんは あした この がっこうへ きます。",
            "image_url": "/assets/assessments/speakers-ab.svg",
            "explanation": "きます menyatakan datang menuju sekolah tempat A berada; dua pilihan lain mengubah arah gerak.",
            "section_label": "えを みて はなす",
            "section_instruction": "えと こえから、Aさんの ことばを えらんで ください。こたえも こえで ききます。\nPerhatikan tokoh A dan situasi dalam audio. Pilih ucapan A; tiga pilihan dibacakan."
          },
